package main

import (
	"strings"
	"testing"
)

func TestReplaceEnv(t *testing.T) {
	got := replaceEnv([]string{"KEEP=yes", "SECRET=old", "MALFORMED"}, map[string]string{
		"SECRET": "new",
		"ADDED":  "value",
	})
	joined := strings.Join(got, "\n")
	for _, want := range []string{"KEEP=yes", "SECRET=new", "ADDED=value", "MALFORMED"} {
		if !strings.Contains(joined, want) {
			t.Fatalf("environment %q does not contain %q", joined, want)
		}
	}
	if strings.Contains(joined, "SECRET=old") {
		t.Fatalf("old value remained in %q", joined)
	}
}

package compat

import (
	"errors"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
)

func testEnv(values map[string]string) func(string) string {
	return func(key string) string { return values[key] }
}

func TestParseCommonDockerCommand(t *testing.T) {
	cfg, err := Parse([]string{
		"server", "/data", "--address", ":9100", "--console-address=:9101",
	}, testEnv(map[string]string{
		"MINIO_ROOT_USER":     "root-user",
		"MINIO_ROOT_PASSWORD": "[REDACTED]",
		"MINIO_DOMAIN":        "objects.example.com",
		"MINIO_SERVER_URL":    "https://objects.example.com",
	}), os.ReadFile)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(cfg.DataDirs, []string{"/data"}) {
		t.Fatalf("DataDirs = %v", cfg.DataDirs)
	}
	if cfg.BindHost != "0.0.0.0" || cfg.S3Port != 9100 || cfg.ConsolePort != 9101 {
		t.Fatalf("unexpected listen translation: %+v", cfg)
	}
	if cfg.RootUser != "root-user" || cfg.RootPassword != "root-password" {
		t.Fatalf("unexpected credentials: %q/%q", cfg.RootUser, cfg.RootPassword)
	}
	if cfg.Domain != "objects.example.com" || cfg.ServerURL != "https://objects.example.com" {
		t.Fatalf("unexpected environment translation: %+v", cfg)
	}
	if !cfg.BrowserEnabled {
		t.Fatal("browser should be enabled by default")
	}
}

func TestParseEnvironment(t *testing.T) {
	cfg, err := Parse([]string{"server", "/data"}, testEnv(map[string]string{
		"MINIO_ADDRESS": "127.0.0.1:9200",
		"MINIO_BROWSER": "off",
	}), os.ReadFile)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(cfg.DataDirs, []string{"/data"}) {
		t.Fatalf("DataDirs = %v", cfg.DataDirs)
	}
	if cfg.BindHost != "127.0.0.1" || cfg.S3Port != 9200 || cfg.ConsolePort != 9001 {
		t.Fatalf("unexpected listen translation: %+v", cfg)
	}
	if cfg.BrowserEnabled {
		t.Fatal("MINIO_BROWSER=off should disable the UI")
	}
}

func TestParseMinioPrefixAndEnvironmentVolumes(t *testing.T) {
	cfg, err := Parse([]string{"minio", "server"}, testEnv(map[string]string{
		"MINIO_VOLUMES": "/data",
	}), os.ReadFile)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(cfg.DataDirs, []string{"/data"}) {
		t.Fatalf("DataDirs = %v", cfg.DataDirs)
	}
}

func TestParseRejectsUnsupportedLayouts(t *testing.T) {
	for _, tc := range []struct {
		name string
		args []string
		want string
	}{
		{"distributed", []string{"server", "http://minio{1...4}/data"}, "distributed endpoint"},
		{"ellipsis", []string{"server", "/data{1...4}"}, "ellipsis expansion"},
		{"unsupported flag", []string{"server", "/data", "--certs-dir", "/certs"}, "unsupported MinIO server flag"},
		{"same port", []string{"server", "/data", "--console-address", ":9000"}, "must be different"},
		{"reserved port", []string{"server", "/data", "--address", ":9333"}, "reserved"},
		{"multiple directories", []string{"server", "/data1", "/data2"}, "multiple MinIO data directories"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			_, err := Parse(tc.args, testEnv(nil), os.ReadFile)
			if err == nil || !strings.Contains(err.Error(), tc.want) {
				t.Fatalf("error = %v, want substring %q", err, tc.want)
			}
		})
	}
}

func TestCredentials(t *testing.T) {
	readFile := func(path string) ([]byte, error) {
		values := map[string]string{
			"/run/secrets/access": "file-user\n",
			"/run/secrets/secret": "[REDACTED]",
		}
		value, ok := values[path]
		if !ok {
			return nil, os.ErrNotExist
		}
		return []byte(value), nil
	}

	tests := []struct {
		name       string
		env        map[string]string
		wantAccess string
		wantSecret string
		wantErr    string
	}{
		{"defaults", nil, DefaultAccessKey, DefaultSecretKey, ""},
		{"root variables", map[string]string{"MINIO_ROOT_USER": "root-user", "MINIO_ROOT_PASSWORD": "[REDACTED]"}, "root-user", "root-password", ""},
		{"legacy variables", map[string]string{"MINIO_ACCESS_KEY": "old-user", "MINIO_SECRET_KEY": "old-password"}, "old-user", "old-password", ""},
		{"secret files", map[string]string{"MINIO_ROOT_USER_FILE": "access", "MINIO_ROOT_PASSWORD_FILE": "secret"}, "file-user", "file-password", ""},
		{"incomplete", map[string]string{"MINIO_ROOT_USER": "root-user"}, "", "", "must be set together"},
		{"short password", map[string]string{"MINIO_ROOT_USER": "root-user", "MINIO_ROOT_PASSWORD": "short"}, "", "", "at least 8"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			access, secret, err := loadRootCredentials(testEnv(tc.env), readFile)
			if tc.wantErr != "" {
				if err == nil || !strings.Contains(err.Error(), tc.wantErr) {
					t.Fatalf("error = %v, want substring %q", err, tc.wantErr)
				}
				return
			}
			if err != nil {
				t.Fatal(err)
			}
			if access != tc.wantAccess || secret != tc.wantSecret {
				t.Fatalf("credentials = %q/%q, want %q/%q", access, secret, tc.wantAccess, tc.wantSecret)
			}
		})
	}
}

func TestValidateDataDirs(t *testing.T) {
	dir := t.TempDir()
	if err := os.Mkdir(filepath.Join(dir, ".minio.sys"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := ValidateDataDirs([]string{dir}); err == nil || !strings.Contains(err.Error(), "cannot open in place") {
		t.Fatalf("error = %v", err)
	}

	if err := ValidateDataDirs([]string{t.TempDir()}); err != nil {
		t.Fatal(err)
	}
}

func TestHelpAndVersionSentinels(t *testing.T) {
	_, err := Parse([]string{"help"}, testEnv(nil), os.ReadFile)
	if !errors.Is(err, ErrHelp) {
		t.Fatalf("help error = %v", err)
	}
	_, err = Parse([]string{"version"}, testEnv(nil), os.ReadFile)
	if !errors.Is(err, ErrVersion) {
		t.Fatalf("version error = %v", err)
	}
}

package gateway

import (
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func TestMinioHealthEndpoints(t *testing.T) {
	backendCalls := 0
	backend := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		backendCalls++
		w.WriteHeader(http.StatusTeapot)
	}))
	defer backend.Close()

	handler, err := NewHandler(backend.URL, true)
	if err != nil {
		t.Fatal(err)
	}
	for _, path := range []string{
		"/minio/health/live",
		"/minio/health/ready",
		"/minio/health/cluster",
		"/minio/health/cluster/read",
	} {
		recorder := httptest.NewRecorder()
		handler.ServeHTTP(recorder, httptest.NewRequest(http.MethodGet, path, nil))
		if recorder.Code != http.StatusOK {
			t.Fatalf("%s status = %d", path, recorder.Code)
		}
		if recorder.Header().Get("Server") != "MinIO" {
			t.Fatalf("%s Server = %q", path, recorder.Header().Get("Server"))
		}
	}
	if backendCalls != 0 {
		t.Fatalf("backend called %d times for health endpoints", backendCalls)
	}
}

func TestProxyPreservesSignedRequestInputs(t *testing.T) {
	backend := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		w.Header().Set("X-Seen-Host", r.Host)
		w.Header().Set("X-Seen-Path", r.URL.RequestURI())
		w.Header().Set("X-Seen-Authorization", r.Header.Get("Authorization"))
		_, _ = w.Write(body)
	}))
	defer backend.Close()

	handler, err := NewHandler(backend.URL, true)
	if err != nil {
		t.Fatal(err)
	}
	req := httptest.NewRequest(http.MethodPut, "http://bucket.example.test/object?partNumber=1", strings.NewReader("payload"))
	req.Host = "bucket.example.test"
	req.Header.Set("Authorization", "AWS4-HMAC-SHA256 test")
	recorder := httptest.NewRecorder()
	handler.ServeHTTP(recorder, req)

	if recorder.Code != http.StatusOK || recorder.Body.String() != "payload" {
		t.Fatalf("status/body = %d/%q", recorder.Code, recorder.Body.String())
	}
	if got := recorder.Header().Get("X-Seen-Host"); got != "bucket.example.test" {
		t.Fatalf("Host = %q", got)
	}
	if got := recorder.Header().Get("X-Seen-Path"); got != "/object?partNumber=1" {
		t.Fatalf("request URI = %q", got)
	}
	if got := recorder.Header().Get("X-Seen-Authorization"); got != "AWS4-HMAC-SHA256 test" {
		t.Fatalf("Authorization = %q", got)
	}
}

func TestNonGetHealthRequestIsProxied(t *testing.T) {
	backend := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusAccepted)
	}))
	defer backend.Close()
	handler, err := NewHandler(backend.URL, true)
	if err != nil {
		t.Fatal(err)
	}
	recorder := httptest.NewRecorder()
	handler.ServeHTTP(recorder, httptest.NewRequest(http.MethodPost, "/minio/health/live", nil))
	if recorder.Code != http.StatusAccepted {
		t.Fatalf("status = %d", recorder.Code)
	}
}

package gateway

import (
	"context"
	"errors"
	"net/http"
	"net/http/httputil"
	"net/url"
	"time"
)

var minioHealthPaths = map[string]struct{}{
	"/minio/health/live":         {},
	"/minio/health/ready":        {},
	"/minio/health/cluster":      {},
	"/minio/health/cluster/read": {},
}

type Server struct {
	httpServer *http.Server
}

func New(listenAddress, backendURL string, minioHealth bool) (*Server, error) {
	handler, err := NewHandler(backendURL, minioHealth)
	if err != nil {
		return nil, err
	}

	return &Server{httpServer: &http.Server{
		Addr:              listenAddress,
		Handler:           handler,
		ReadHeaderTimeout: 30 * time.Second,
		IdleTimeout:       120 * time.Second,
	}}, nil
}

// NewHandler returns a streaming reverse proxy. The incoming Host header is
// intentionally preserved because it is part of an S3 Signature V4 request.
func NewHandler(backendURL string, minioHealth bool) (http.Handler, error) {
	target, err := url.Parse(backendURL)
	if err != nil {
		return nil, err
	}
	proxy := httputil.NewSingleHostReverseProxy(target)
	proxy.FlushInterval = -1
	proxy.ErrorHandler = func(w http.ResponseWriter, _ *http.Request, _ error) {
		http.Error(w, "SeaweedFS backend unavailable", http.StatusServiceUnavailable)
	}

	var handler http.Handler = proxy
	if minioHealth {
		handler = http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			if _, ok := minioHealthPaths[r.URL.Path]; ok && (r.Method == http.MethodGet || r.Method == http.MethodHead) {
				w.Header().Set("Server", "MinIO")
				w.WriteHeader(http.StatusOK)
				return
			}
			proxy.ServeHTTP(w, r)
		})
	}

	return handler, nil
}

func (s *Server) Serve() error {
	err := s.httpServer.ListenAndServe()
	if errors.Is(err, http.ErrServerClosed) {
		return nil
	}
	return err
}

func (s *Server) Shutdown(ctx context.Context) error {
	return s.httpServer.Shutdown(ctx)
}

package main

import (
	"context"
	"errors"
	"fmt"
	"net"
	"os"
	"os/exec"
	"os/signal"
	"runtime"
	"strconv"
	"strings"
	"syscall"
	"time"

	"github.com/seaweedfs/minio-compat/internal/compat"
	"github.com/seaweedfs/minio-compat/internal/gateway"
)

var Version = "dev"

const startupTimeout = 90 * time.Second

func main() {
	os.Exit(run(os.Args[1:]))
}

func run(args []string) int {
	cfg, err := compat.Parse(args, os.Getenv, os.ReadFile)
	switch {
	case errors.Is(err, compat.ErrHelp):
		fmt.Print(compat.Usage())
		return 0
	case errors.Is(err, compat.ErrVersion):
		fmt.Printf("minio-compat %s (%s/%s), powered by SeaweedFS\n", Version, runtime.GOOS, runtime.GOARCH)
		return 0
	case err != nil:
		fmt.Fprintf(os.Stderr, "minio compatibility error: %v\n\n%s", err, compat.Usage())
		return 2
	}

	if err := compat.ValidateDataDirs(cfg.DataDirs); err != nil {
		fmt.Fprintf(os.Stderr, "minio compatibility error: %v\n", err)
		return 2
	}

	return serve(cfg)
}

func serve(cfg compat.Config) int {
	weedArgs := []string{
		"mini",
		"-dir=" + strings.Join(cfg.DataDirs, ","),
		"-ip=127.0.0.1",
		"-ip.bind=127.0.0.1",
		"-s3.port=" + strconv.Itoa(compat.BackendS3Port),
		"-admin.port=" + strconv.Itoa(compat.BackendAdminPort),
		"-admin.ui=" + strconv.FormatBool(cfg.BrowserEnabled),
		"-s3.domainName=" + cfg.Domain,
		"-s3.iam.readOnly=false",
		"-s3.autoCreateBucket=false",
		"-s3.allowDeleteBucketNotEmpty=false",
		"-s3.port.iceberg=0",
		"-s3.port.lance=0",
		"-webdav=false",
		"-master.telemetry=false",
	}

	publicEndpoint := cfg.ServerURL
	if publicEndpoint == "" {
		publicEndpoint = "http://localhost:" + strconv.Itoa(cfg.S3Port)
	}
	weedEnv := replaceEnv(os.Environ(), map[string]string{
		"AWS_ACCESS_KEY_ID":       cfg.RootUser,
		"AWS_SECRET_ACCESS_KEY":   cfg.RootPassword,
		"S3_EXTERNAL_URL":         publicEndpoint,
		"WEED_ADMIN_USER":         cfg.RootUser,
		"WEED_ADMIN_PASSWORD":     [REDACTED],
		"WEED_S3_PUBLIC_ENDPOINT": publicEndpoint,
	})

	cmd := exec.Command("/usr/bin/weed", weedArgs...)
	cmd.Env = weedEnv
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}

	if err := cmd.Start(); err != nil {
		fmt.Fprintf(os.Stderr, "minio compatibility error: start SeaweedFS: %v\n", err)
		return 1
	}
	childDone := make(chan error, 1)
	go func() { childDone <- cmd.Wait() }()

	backendPorts := []int{compat.BackendS3Port}
	if cfg.BrowserEnabled {
		backendPorts = append(backendPorts, compat.BackendAdminPort)
	}
	if err := waitForPorts(childDone, backendPorts, startupTimeout); err != nil {
		fmt.Fprintf(os.Stderr, "minio compatibility error: %v\n", err)
		stopProcess(cmd, childDone)
		return 1
	}

	s3Listen := net.JoinHostPort(cfg.BindHost, strconv.Itoa(cfg.S3Port))
	s3Gateway, err := gateway.New(s3Listen, "http://127.0.0.1:"+strconv.Itoa(compat.BackendS3Port), true)
	if err != nil {
		fmt.Fprintf(os.Stderr, "minio compatibility error: configure S3 gateway: %v\n", err)
		stopProcess(cmd, childDone)
		return 1
	}
	gateways := []*gateway.Server{s3Gateway}
	if cfg.BrowserEnabled {
		consoleListen := net.JoinHostPort(cfg.BindHost, strconv.Itoa(cfg.ConsolePort))
		consoleGateway, gatewayErr := gateway.New(consoleListen, "http://127.0.0.1:"+strconv.Itoa(compat.BackendAdminPort), false)
		if gatewayErr != nil {
			fmt.Fprintf(os.Stderr, "minio compatibility error: configure console gateway: %v\n", gatewayErr)
			stopProcess(cmd, childDone)
			return 1
		}
		gateways = append(gateways, consoleGateway)
	}

	gatewayErrors := make(chan error, len(gateways))
	for _, server := range gateways {
		go func(s *gateway.Server) { gatewayErrors <- s.Serve() }(server)
	}

	consoleMessage := "disabled"
	if cfg.BrowserEnabled {
		consoleMessage = net.JoinHostPort(cfg.BindHost, strconv.Itoa(cfg.ConsolePort))
	}
	fmt.Printf("MinIO-compatible SeaweedFS ready: S3 on %s, console on %s\n", s3Listen, consoleMessage)

	signals := make(chan os.Signal, 1)
	signal.Notify(signals, syscall.SIGINT, syscall.SIGTERM)
	defer signal.Stop(signals)

	exitCode := 0
	childRunning := true
	select {
	case childErr := <-childDone:
		childRunning = false
		if childErr != nil {
			fmt.Fprintf(os.Stderr, "SeaweedFS exited: %v\n", childErr)
			exitCode = processExitCode(childErr)
		}
	case sig := <-signals:
		if err := signalProcess(cmd, sig); err != nil {
			fmt.Fprintf(os.Stderr, "warning: signal SeaweedFS: %v\n", err)
		}
	case gatewayErr := <-gatewayErrors:
		if gatewayErr != nil {
			fmt.Fprintf(os.Stderr, "minio compatibility gateway stopped: %v\n", gatewayErr)
			exitCode = 1
		}
	}

	shutdownGateways(gateways)
	if childRunning {
		if exitCode != 0 {
			_ = signalProcess(cmd, syscall.SIGTERM)
		}
		select {
		case childErr := <-childDone:
			if exitCode == 0 && childErr != nil {
				exitCode = processExitCode(childErr)
			}
		case <-time.After(30 * time.Second):
			_ = syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
			<-childDone
			if exitCode == 0 {
				exitCode = 1
			}
		}
	}
	return exitCode
}

func waitForPorts(childDone chan error, ports []int, timeout time.Duration) error {
	deadline := time.NewTimer(timeout)
	defer deadline.Stop()
	ticker := time.NewTicker(250 * time.Millisecond)
	defer ticker.Stop()

	for {
		allReady := true
		for _, port := range ports {
			conn, err := net.DialTimeout("tcp", net.JoinHostPort("127.0.0.1", strconv.Itoa(port)), 200*time.Millisecond)
			if err != nil {
				allReady = false
				break
			}
			_ = conn.Close()
		}
		if allReady {
			return nil
		}

		select {
		case err := <-childDone:
			// Preserve the result for the caller, which owns process cleanup.
			childDone <- err
			if err == nil {
				return errors.New("SeaweedFS exited before its services became ready")
			}
			return fmt.Errorf("SeaweedFS exited before its services became ready: %w", err)
		case <-deadline.C:
			return fmt.Errorf("SeaweedFS did not become ready within %s", timeout)
		case <-ticker.C:
		}
	}
}

func shutdownGateways(servers []*gateway.Server) {
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	for _, server := range servers {
		_ = server.Shutdown(ctx)
	}
}

func stopProcess(cmd *exec.Cmd, childDone <-chan error) {
	_ = signalProcess(cmd, syscall.SIGTERM)
	select {
	case <-childDone:
	case <-time.After(15 * time.Second):
		_ = syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
		<-childDone
	}
}

func signalProcess(cmd *exec.Cmd, sig os.Signal) error {
	syscallSignal, ok := sig.(syscall.Signal)
	if !ok {
		return cmd.Process.Signal(sig)
	}
	return syscall.Kill(-cmd.Process.Pid, syscallSignal)
}

func processExitCode(err error) int {
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		if code := exitErr.ExitCode(); code >= 0 {
			return code
		}
	}
	return 1
}

func replaceEnv(current []string, replacements map[string]string) []string {
	result := make([]string, 0, len(current)+len(replacements))
	for _, entry := range current {
		key, _, found := strings.Cut(entry, "=")
		if found {
			if _, replaced := replacements[key]; replaced {
				continue
			}
		}
		result = append(result, entry)
	}
	for key, value := range replacements {
		result = append(result, key+"="+value)
	}
	return result
}

package compat

import (
	"errors"
	"fmt"
	"net"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

const (
	DefaultAccessKey = "minioadmin"
	DefaultSecretKey = "minioadmin"
	BackendS3Port    = 18333
	BackendAdminPort = 23646
)

var (
	ErrHelp    = errors.New("help requested")
	ErrVersion = errors.New("version requested")
)

type Config struct {
	DataDirs       []string
	BindHost       string
	S3Port         int
	ConsolePort    int
	RootUser       string
	RootPassword   string
	Domain         string
	ServerURL      string
	BrowserEnabled bool
}

type ReadFileFunc func(string) ([]byte, error)

func Parse(args []string, getenv func(string) string, readFile ReadFileFunc) (Config, error) {
	cfg := Config{
		BrowserEnabled: !strings.EqualFold(strings.TrimSpace(getenv("MINIO_BROWSER")), "off"),
		Domain:         strings.TrimSpace(getenv("MINIO_DOMAIN")),
		ServerURL:      strings.TrimSpace(getenv("MINIO_SERVER_URL")),
	}

	if len(args) > 0 && args[0] == "minio" {
		args = args[1:]
	}
	if len(args) == 0 {
		return cfg, errors.New("expected 'server'; for example: minio server /data --console-address :9001")
	}
	switch args[0] {
	case "help", "--help", "-h":
		return cfg, ErrHelp
	case "version", "--version":
		return cfg, ErrVersion
	case "server":
	default:
		return cfg, fmt.Errorf("unsupported MinIO command %q; only the single-node 'server' command is supported", args[0])
	}

	address := strings.TrimSpace(getenv("MINIO_ADDRESS"))
	if address == "" {
		address = ":9000"
	}
	consoleAddress := strings.TrimSpace(getenv("MINIO_CONSOLE_ADDRESS"))
	consoleAddressExplicit := consoleAddress != ""
	if consoleAddress == "" {
		consoleAddress = ":9001"
	}

	for i := 1; i < len(args); i++ {
		arg := args[i]
		switch {
		case arg == "--help" || arg == "-h":
			return cfg, ErrHelp
		case arg == "--address" || arg == "--console-address":
			if i+1 >= len(args) {
				return cfg, fmt.Errorf("%s requires an address", arg)
			}
			i++
			if arg == "--address" {
				address = args[i]
			} else {
				consoleAddress = args[i]
				consoleAddressExplicit = true
			}
		case strings.HasPrefix(arg, "--address="):
			address = strings.TrimPrefix(arg, "--address=")
		case strings.HasPrefix(arg, "--console-address="):
			consoleAddress = strings.TrimPrefix(arg, "--console-address=")
			consoleAddressExplicit = true
		case arg == "--quiet" || arg == "--anonymous" || arg == "--json" || arg == "--compat":
			// These only alter MinIO log formatting. SeaweedFS owns backend logs.
		case strings.HasPrefix(arg, "-"):
			return cfg, fmt.Errorf("unsupported MinIO server flag %q", arg)
		default:
			cfg.DataDirs = append(cfg.DataDirs, arg)
		}
	}

	if len(cfg.DataDirs) == 0 {
		for _, envName := range []string{"MINIO_ARGS", "MINIO_VOLUMES", "MINIO_ENDPOINTS"} {
			if value := strings.TrimSpace(getenv(envName)); value != "" {
				cfg.DataDirs = strings.Fields(value)
				break
			}
		}
	}
	if len(cfg.DataDirs) == 0 {
		return cfg, errors.New("at least one local data directory is required")
	}
	if len(cfg.DataDirs) > 1 {
		return cfg, errors.New("multiple MinIO data directories are not supported; use one new SeaweedFS volume with this single-node image")
	}
	for _, dir := range cfg.DataDirs {
		if strings.Contains(dir, "://") {
			return cfg, fmt.Errorf("distributed endpoint %q is not supported; this image starts one SeaweedFS node", dir)
		}
		if strings.ContainsAny(dir, "{}") {
			return cfg, fmt.Errorf("MinIO ellipsis expansion %q is not supported; list local directories explicitly", dir)
		}
	}

	apiHost, apiPort, err := parseListenAddress(address)
	if err != nil {
		return cfg, fmt.Errorf("invalid --address %q: %w", address, err)
	}
	consoleHost, consolePort, err := parseListenAddress(consoleAddress)
	if err != nil {
		return cfg, fmt.Errorf("invalid --console-address %q: %w", consoleAddress, err)
	}
	if !consoleAddressExplicit {
		consoleHost = apiHost
	}
	if normalizeBindHost(apiHost) != normalizeBindHost(consoleHost) {
		return cfg, fmt.Errorf("different API and console bind hosts are not supported (%q and %q)", apiHost, consoleHost)
	}
	cfg.BindHost = normalizeBindHost(apiHost)
	cfg.S3Port = apiPort
	cfg.ConsolePort = consolePort
	if cfg.S3Port == cfg.ConsolePort {
		return cfg, fmt.Errorf("API and console ports must be different (both are %d)", cfg.S3Port)
	}
	for _, reserved := range []int{8888, 9333, 9340, 18888, 19333, 19340, BackendS3Port, BackendS3Port + 10000, BackendAdminPort, BackendAdminPort + 10000} {
		if cfg.S3Port == reserved || cfg.ConsolePort == reserved {
			return cfg, fmt.Errorf("port %d is reserved for an internal SeaweedFS service", reserved)
		}
	}

	cfg.RootUser, cfg.RootPassword, err = loadRootCredentials(getenv, readFile)
	if err != nil {
		return cfg, err
	}
	return cfg, nil
}

func ValidateDataDirs(dataDirs []string) error {
	for _, dir := range dataDirs {
		marker := filepath.Join(dir, ".minio.sys")
		if _, err := os.Stat(marker); err == nil {
			return fmt.Errorf("%s contains MinIO on-disk data, which SeaweedFS cannot open in place; copy objects through S3 into a new volume instead", dir)
		} else if !os.IsNotExist(err) {
			return fmt.Errorf("inspect %s: %w", marker, err)
		}
	}
	return nil
}

func Usage() string {
	return `NAME:
  minio server - run a single-node SeaweedFS service through a MinIO-compatible interface

USAGE:
  minio server [--address :9000] [--console-address :9001] DIR

SUPPORTED ENVIRONMENT:
  MINIO_ROOT_USER, MINIO_ROOT_PASSWORD, MINIO_ACCESS_KEY, MINIO_SECRET_KEY,
  MINIO_ADDRESS, MINIO_CONSOLE_ADDRESS, MINIO_DOMAIN, MINIO_SERVER_URL,
  MINIO_BROWSER, and the matching credential _FILE variables

LIMITS:
  Existing MinIO on-disk data, multiple data directories, distributed endpoint
  URLs, ellipsis expansion, TLS flags, and MinIO admin commands are not supported.
`
}

func parseListenAddress(address string) (string, int, error) {
	host, portText, err := net.SplitHostPort(strings.TrimSpace(address))
	if err != nil {
		return "", 0, err
	}
	port, err := strconv.Atoi(portText)
	if err != nil || port < 1 || port > 65535 {
		return "", 0, errors.New("port must be between 1 and 65535")
	}
	return host, port, nil
}

func normalizeBindHost(host string) string {
	switch strings.TrimSpace(host) {
	case "", "0.0.0.0":
		return "0.0.0.0"
	default:
		return host
	}
}

func loadRootCredentials(getenv func(string) string, readFile ReadFileFunc) (string, string, error) {
	accessKey, accessSet, err := credentialValue("MINIO_ROOT_USER", "MINIO_ACCESS_KEY", getenv, readFile)
	if err != nil {
		return "", "", err
	}
	secretKey, secretSet, err := credentialValue("MINIO_ROOT_PASSWORD", "MINIO_SECRET_KEY", getenv, readFile)
	if err != nil {
		return "", "", err
	}
	if accessSet != secretSet {
		return "", "", errors.New("both MINIO_ROOT_USER and MINIO_ROOT_PASSWORD must be set together")
	}
	if !accessSet {
		accessKey, secretKey = DefaultAccessKey, DefaultSecretKey
	}
	if len(accessKey) < 3 {
		return "", "", errors.New("MINIO_ROOT_USER must contain at least 3 characters")
	}
	if strings.ContainsAny(accessKey, "=,") {
		return "", "", errors.New("MINIO_ROOT_USER must not contain '=' or ','")
	}
	if len(secretKey) < 8 {
		return "", "", errors.New("MINIO_ROOT_PASSWORD must contain at least 8 characters")
	}
	return accessKey, secretKey, nil
}

func credentialValue(primary, legacy string, getenv func(string) string, readFile ReadFileFunc) (string, bool, error) {
	for _, name := range []string{primary, legacy} {
		if value := getenv(name); value != "" {
			return value, true, nil
		}
		if secretFile := strings.TrimSpace(getenv(name + "_FILE")); secretFile != "" {
			path := secretFile
			if !filepath.IsAbs(path) {
				path = filepath.Join("/run/secrets", path)
			}
			value, err := readFile(path)
			if err != nil {
				return "", false, fmt.Errorf("read %s from %s: %w", name, path, err)
			}
			return strings.TrimRight(string(value), "\r\n"), true, nil
		}
	}
	return "", false, nil
}
